import limited_client as robot, numpy as np
for cam in (0,1,2,3):
 ob=robot.observe(camera=cam)
 print('CAM',cam,'status',robot.status(),'robot',ob['robot'])
 if cam==2:
  K,T,d=ob['intrinsic'],ob['camera_to_world'],ob['depth_m']; W=np.linalg.inv(T)
  c=W@np.r_[ob['robot']['tcp_position'],1]; print('TCP uv/depth',((K@c[:3])[:2]/c[2]).round(1),round(float(c[2]),3))
  for label,pts in {'Mickey':[(250,270),(260,275),(270,280),(260,285),(270,290)],'box':[(130,210),(140,220),(150,230)]}.items():
   for uv in pts:
    u,v=uv; z=float(np.median(d[max(0,v-2):v+3,max(0,u-2):u+3])); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); print(label,uv,round(z,3),(T@p)[:3].round(3))
